"""Compact temporal candidate policy with safety gating and bounded action memory."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or closing risk is high."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Use a brief stop for uncertain reacquisition, then alternate bounded scans."""
    reliable = (
        bool(observation["target_visible"])
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        if int(observation["track_age"]) < 1:
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.82
        return None

    lost_steps = int(observation["lost_steps"])
    prior_state = memory.get("state")
    if prior_state in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.93

    direction = memory.get("scan_direction", "SCAN_LEFT")
    memory["scan_direction"] = (
        "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
    )
    memory["state"] = "SEARCH"
    return direction, 0.76


def propose_moves(observation, memory):
    """Generate corridor-valid moves ordered by bearing alignment and forward progress."""
    bearing = float(observation["target_bearing"])
    candidates = []

    if bearing <= -12.0 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if bearing >= 12.0 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")

    unique = []
    for action in candidates:
        if action not in unique:
            unique.append(action)
    return unique


def progress_contract(observation, memory, candidates):
    """Prefer aligned forward motion and suppress needless alternating turns."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    previous = memory.get("last_action")
    streak = int(memory.get("turn_streak", 0))

    def cost(action):
        value = 0.0
        if action == "FORWARD":
            value += abs(bearing) * 0.018
            if abs(bearing) <= 10.0:
                value -= 0.28
        elif action == "VEER_LEFT":
            value += max(0.0, bearing) * 0.012
            if bearing < -10.0:
                value -= 0.16
        elif action == "VEER_RIGHT":
            value += max(0.0, -bearing) * 0.012
            if bearing > 10.0:
                value -= 0.16

        if previous in {"VEER_LEFT", "VEER_RIGHT"} and action != previous:
            value += 0.05
        if action == previous and action != "FORWARD" and streak >= 2:
            value += 0.12
        return value

    action = min(candidates, key=cost)
    if action == previous:
        memory["turn_streak"] = streak + 1
    elif action in {"VEER_LEFT", "VEER_RIGHT"}:
        memory["turn_streak"] = 1
    else:
        memory["turn_streak"] = 0

    memory["last_action"] = action
    history = list(memory.get("recent_actions", []))
    history.append(action)
    memory["recent_actions"] = history[-6:]
    return action


def termination_contract(observation, memory):
    """Return a high-confidence stop when no safe movement proposal exists."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination contracts."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory

        bearing = float(observation["target_bearing"])
        if bearing < 0.0 and observation["corridor_left"]:
            candidates = ["VEER_LEFT"]
        elif bearing >= 0.0 and observation["corridor_right"]:
            candidates = ["VEER_RIGHT"]
        else:
            candidates = propose_moves(observation, memory)
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
